"""Offline integration tests. Every media fixture is generated by ffmpeg."""
import base64
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import subprocess
import sys
import threading
import time

import cv2
import numpy as np
import pytest

from sam import Config, clear_cache, clip_masks, render_effect, subject_track
from sam.backends import fallback_mask
from sam.effects import composite


def run(*args):
    return subprocess.run(args, check=True, capture_output=True, timeout=30).stdout


@pytest.fixture(scope="module")
def video(tmp_path_factory):
    path = tmp_path_factory.mktemp("synthetic")/"motion.mp4"
    run("ffmpeg", "-v", "error", "-y", "-f", "lavfi", "-i", "color=c=black:s=160x96:r=12:d=2",
        "-f", "lavfi", "-i", "sine=frequency=440:sample_rate=48000:duration=2",
        "-vf", "drawtext=text='X':fontsize=32:fontcolor=white:x=35+20*t:y=32",
        "-c:v", "libx264", "-pix_fmt", "yuv420p", "-c:a", "aac", "-shortest", str(path))
    return path


@pytest.fixture(autouse=True)
def cache():
    clear_cache()
    yield
    clear_cache()


@pytest.fixture
def endpoint():
    state = {"calls": [], "mode": "ok"}
    class Handler(BaseHTTPRequestHandler):
        def log_message(self, *args):
            pass

        def do_POST(self):
            data = json.loads(self.rfile.read(int(self.headers["Content-Length"])))
            state["calls"].append((data["prompt"], self.headers.get("Authorization")))
            if state["mode"] == "slow":
                time.sleep(2)
            frame = cv2.imdecode(np.frombuffer(base64.b64decode(data["image_png"]), np.uint8), cv2.IMREAD_COLOR)
            mask = np.zeros(frame.shape[:2], np.uint8)
            mask[20:70, 45:85] = 1
            payload = json.dumps({"mask": mask.tolist() if state["mode"] != "bad" else [[1]]}).encode()
            try:
                self.send_response(200)
                self.send_header("Content-Type", "application/json")
                self.send_header("Content-Length", str(len(payload)))
                self.end_headers()
                self.wfile.write(payload)
            except (BrokenPipeError, ConnectionResetError):
                pass
    server = ThreadingHTTPServer(("127.0.0.1", 0), Handler)
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    yield f"http://127.0.0.1:{server.server_port}/segment", state
    server.shutdown()
    server.server_close()
    thread.join(timeout=2)


def test_fallback_masks_cache_and_moving_track(video):
    clip = clip_masks(video, 0, 2)
    assert clip.masks.shape == (9, 96, 160)
    assert set(np.unique(clip.masks)) <= {0, 1}
    assert np.all(clip.masks.sum(axis=(1, 2)) > 0)
    assert clip_masks(video, 0, 2) is clip
    assert not clip.masks.flags.writeable
    track = np.array(subject_track(video, 0, 2))
    assert track.shape == (24, 5)
    assert np.all((track[:, 1:] >= 0) & (track[:, 1:] <= 1))
    assert np.allclose(np.diff(track[:, 0]), 1/12)
    assert np.max(np.abs(np.diff(track[:, 1:], axis=0))) <= .6/12 + 1e-8
    assert track[-1, 1] > track[0, 1]+.10
    assert clip_masks(video, .5, 1.5) is not clip
    assert subject_track(video, .5, 1.5)[0][0] == .5


def test_blank_fallback_is_stable():
    frame = np.zeros((40, 60, 3), np.uint8)
    mask = fallback_mask(frame)
    assert mask.shape == (40, 60)
    assert 0 < mask.sum() < mask.size
    assert np.array_equal(mask, fallback_mask(frame, frame))


def test_remote_contract_and_cache(video, endpoint):
    url, state = endpoint
    config = Config(backend="remote", url=url, key="test-only", timeout=3, budget=10, max_samples=3)
    clip = clip_masks(video, 0, 2, config=config, prompt="enemy")
    assert not clip.degraded
    assert len(state["calls"]) == 3
    assert all(call == ("enemy", "Bearer test-only") for call in state["calls"])
    assert np.all(clip.masks[:, 20:70, 45:85] == 1)
    assert np.all(clip.masks.sum(axis=(1, 2)) == 2000)
    assert clip_masks(video, 0, 2, config=config, prompt="enemy") is clip
    assert len(state["calls"]) == 3
    assert "test-only" not in repr(config)


@pytest.mark.parametrize("mode", ["bad", "slow"])
def test_remote_failure_is_bounded_and_falls_back(video, endpoint, mode):
    url, state = endpoint
    state["mode"] = mode
    started = time.monotonic()
    clip = clip_masks(video, 0, 2, config=Config(backend="remote", url=url, timeout=1, budget=1))
    elapsed = time.monotonic()-started
    assert clip.degraded
    assert elapsed < 2.5
    assert len(state["calls"]) <= 1
    assert np.array_equal(clip.masks, clip_masks(video, 0, 2).masks)


def test_missing_local_model_falls_back(video):
    started = time.monotonic()
    clip = clip_masks(video, 0, 2, config=Config(backend="local", checkpoint="/missing/model.pt", timeout=1))
    assert clip.degraded
    assert time.monotonic()-started < 2.5
    assert np.array_equal(clip.masks, clip_masks(video, 0, 2).masks)


@pytest.mark.parametrize("effect,vertical,duration", [
    ("outline_pulse", False, 1.5), ("background_blur", True, 1.5), ("spotlight_freeze", False, 2.0)])
def test_render_duration_geometry_audio_and_decode(video, tmp_path, effect, vertical, duration):
    result = render_effect(video, tmp_path/f"{effect}.mp4", .25, 1.75, effect=effect,
                           vertical=vertical, size=(90, 160), kill_time=1, freeze_seconds=.5)
    metadata = json.loads(run("ffprobe", "-v", "error", "-show_streams", "-show_format", "-of", "json", str(result)))
    streams = {stream["codec_type"]: stream for stream in metadata["streams"]}
    assert float(metadata["format"]["duration"]) == pytest.approx(duration, abs=.06)
    assert float(streams["audio"]["duration"]) == pytest.approx(duration, abs=.06)
    assert (streams["video"]["width"], streams["video"]["height"]) == ((90, 160) if vertical else (160, 96))
    assert int(streams["video"]["nb_frames"]) == round(duration*12)
    run("ffmpeg", "-v", "error", "-i", str(result), "-f", "null", "-")
    if effect == "spotlight_freeze":
        audio = np.frombuffer(run("ffmpeg", "-v", "error", "-i", str(result), "-f", "f32le", "-ac", "1", "-ar", "48000", "-"), np.float32)
        # Freeze is inserted after kill frame: source .25 -> 1.0833 = .8333 s.
        assert np.sqrt(np.mean(audio[int(.95*48000):int(1.2*48000)]**2)) < .005
        assert np.sqrt(np.mean(audio[int(1.5*48000):int(1.7*48000)]**2)) > .02
        original = cv2.VideoCapture(str(video))
        rendered = cv2.VideoCapture(str(result))
        try:
            original.set(cv2.CAP_PROP_POS_FRAMES, 13)
            ok_source, expected = original.read()
            rendered.set(cv2.CAP_PROP_POS_FRAMES, 16)
            ok_output, resumed = rendered.read()
            assert ok_source and ok_output
            assert np.abs(expected.astype(float)-resumed).mean() < 5
            rendered.set(cv2.CAP_PROP_POS_FRAMES, 12)
            ok_hold, held = rendered.read()
            assert ok_hold
            assert np.abs(held.astype(float)-expected).mean() > 5
        finally:
            original.release()
            rendered.release()


def test_silent_video_and_last_frame_freeze(video, tmp_path):
    silent = tmp_path/"silent.mp4"
    run("ffmpeg", "-v", "error", "-i", str(video), "-c:v", "copy", "-an", str(silent))
    output = render_effect(silent, tmp_path/"out.mp4", 0, 2, effect="spotlight_freeze", kill_time=23/12, freeze_seconds=.5)
    metadata = json.loads(run("ffprobe", "-v", "error", "-show_streams", "-of", "json", str(output)))
    assert len(metadata["streams"]) == 1
    assert int(metadata["streams"][0]["nb_frames"]) == 30
    render_effect(video, tmp_path/"audio-last.mp4", 0, 2, effect="spotlight_freeze", kill_time=23/12)


def test_compositing_changes_background_and_preserves_subject():
    frame = np.random.default_rng(1).integers(0, 255, (96, 160, 3), dtype=np.uint8)
    mask = np.zeros((96, 160), np.uint8)
    mask[30:70, 50:100] = 1
    blurred = composite(frame, mask, "background_blur")
    assert np.array_equal(blurred[mask == 1], frame[mask == 1])
    assert np.std(blurred[mask == 0]) < np.std(frame[mask == 0])/2
    spotlight = composite(frame, mask, "spotlight_freeze")
    assert spotlight[:10].mean() < frame[:10].mean()*.5
    assert not np.array_equal(composite(frame, mask, "outline_pulse", 0), composite(frame, mask, "outline_pulse", .25))


@pytest.mark.parametrize("start,end", [(-1, 1), (1, 1), (2, 1), (10, 11), (float("nan"), 2)])
def test_invalid_clip(video, start, end):
    with pytest.raises(ValueError):
        clip_masks(video, start, end)


def test_atomic_output_on_encode_failure(video, tmp_path, monkeypatch):
    import sam.effects as effects
    output = tmp_path/"existing.mp4"
    output.write_bytes(b"existing")
    def fail(*args):
        raise RuntimeError("encoder failed")
    monkeypatch.setattr(effects, "_run", fail)
    with pytest.raises(RuntimeError, match="encoder failed"):
        render_effect(video, output, 0, 1)
    assert output.read_bytes() == b"existing"
    assert list(tmp_path.iterdir()) == [output]


def test_render_survives_remote_failure(video, tmp_path, endpoint):
    url, state = endpoint
    state["mode"] = "bad"
    result = render_effect(video, tmp_path/"fallback.mp4", 0, 1,
                           config=Config(backend="remote", url=url, timeout=2))
    run("ffmpeg", "-v", "error", "-i", str(result), "-f", "null", "-")
    assert len(state["calls"]) == 1


def test_remote_total_budget(video, endpoint):
    url, state = endpoint
    state["mode"] = "slow"
    started = time.monotonic()
    clip = clip_masks(video, 0, 2, config=Config(backend="remote", url=url, timeout=5, budget=.8))
    assert clip.degraded
    assert time.monotonic()-started < 2
    assert len(state["calls"]) <= 1


def test_cli(video, tmp_path):
    output = tmp_path/"cli.mp4"
    run(sys.executable, "-m", "sam", str(video), str(output), "--end", "1",
        "--effect", "background_blur", "--vertical")
    metadata = json.loads(run("ffprobe", "-v", "error", "-show_streams", "-of", "json", str(output)))
    assert metadata["streams"][0]["width"] == 720
    assert metadata["streams"][0]["height"] == 1280
